# 2D RoPE: 차원 절반은 행, 절반은 열 위치로 돌린다 → 점수는 (Δ행, Δ열)에만 의존
import numpy as np
def rot2(v, m, th):
    c, s = np.cos(m * th), np.sin(m * th)
    return np.array([c * v[0] - s * v[1], s * v[0] + c * v[1]])
def rope2d(v, r, c, th=0.3):                      # v 는 4차원: [행용 2 | 열용 2]
    return np.concatenate([rot2(v[:2], r, th), rot2(v[2:], c, th)])
q, k = np.array([1., 2., -1., 0.5]), np.array([0.5, 1., 2., -1.])
for (r1, c1), (r2, c2) in [((3, 4), (1, 1)), ((10, 9), (8, 6)), ((5, 5), (3, 2))]:
    s = rope2d(q, r1, c1) @ rope2d(k, r2, c2)
    print(f"q@({r1},{c1}) k@({r2},{c2}) Δ=({r1-r2},{c1-c2}) 점수={s:.6f}")
